7: void l2_cache::force_tag_access(new_addr_type addr, unsigned time,
8:                                 mem_access_sector_mask_t mask) {
9:   if (!ft_enabled()) { baseline_cache::force_tag_access(addr, time, mask); return; }
10:   if(m_ro)m_ro->prefill_begin(m_config.block_addr(addr));
11:   if (!ft_try_force_tag_access(addr, time, mask)) {
12:     fprintf(stderr, "EP-L2 host prefill requires quiescent clean ownership; no pending/dirty victim may be discarded\n");
13:     abort();
14:   }
15: }
