17: bool l2_cache::ft_try_force_tag_access(new_addr_type addr, unsigned time,
18:                                       mem_access_sector_mask_t mask) {
19:   if(m_ro && !m_ro->prefill_allowed(m_config.block_addr(addr)))return false;
20:   // This is untimed host initialization, not a source of GPU bank grants or
21:   // free WB service. Fail BEFORE changing Tag, generation, owner or offset.
22:   if (!ft_enabled() || m_config.m_cache_type != SECTOR || mask.count() != 1 ||
23:       !ft_drained() || ep_l2_wad_occupancy() || m_tvd_lookup || m_tvd_read ||
24:       mshr_entries_used() || !miss_queue_empty() ||
25:       m_ep_l2_payload.pending_sector_count() || m_ep_l2_payload.pending_operations())
26:     return false;
27:   const new_addr_type owner = m_config.block_addr(addr);
28:   unsigned index = (unsigned)-1;
29:   const cache_request_status status = m_tag_array->probe(owner, index, mask, true, true);
30:   if (status == RESERVATION_FAIL || status == HIT_RESERVED ||
31:       index >= m_config.get_num_lines() || m_tag_array->block_is_modified(index) ||
32:       m_tag_array->get_block(index)->is_reserved_line())
33:     return false;
34:   ep_l2::PayloadHandle handle = tag_payload_handle(index);
35:   const bool live = m_ep_l2_payload.handle_live(handle);
36:   if (live) {
37:     const ep_l2_payload_store::slot &old = m_ep_l2_payload.inspect(handle);
38:     if (old.allocation_role != ep_l2_payload_store::RESIDENT || old.pins ||
39:         old.pending_sector_mask.any() || old.status == ep_l2_payload_store::RESIDENT_DIRTY ||
40:         handle.payload_id % 4 != index % 4)
41:       return false;
42:   }
43:   // TVD is another visibility of this exact host address. Preview all guards
44:   // before removing its optional copy; failed try-prefill changes no state.
45:   const auto alias = m_tvd ? m_tvd->find(owner) : tvd_directory::ticket();
46:   const bool has_alias = m_tvd && m_tvd->live(alias);
47:   ep_l2::PayloadHandle alias_payload;
48:   if (has_alias) {
49:     const auto &entry = m_tvd->at(alias.index);
50:     alias_payload = entry.payload;
51:     if (status != MISS || !entry.reclaimable() ||
52:         entry.incarnation == std::numeric_limits<std::uint64_t>::max() ||
53:         !m_ep_l2_payload.handle_owner_matches(alias_payload, owner))
54:       return false;
55:     const auto &slot = m_ep_l2_payload.inspect(alias_payload);
56:     if (slot.allocation_role != ep_l2_payload_store::TVD || slot.pins ||
57:         slot.pending_sector_mask.any() ||
58:         alias_payload.generation == std::numeric_limits<unsigned>::max())
59:       return false;
60:   }
61:   unsigned landing = index;
62:   if (status == MISS) {
63:     if (live) {
64:       // release and reserve each advance the generation; check both before
65:       // mutating either visibility. Epoch exhaustion is a refusal, not reuse.
66:       if (handle.generation >= std::numeric_limits<unsigned>::max() - 1)
67:         return false;
68:       landing = handle.payload_id;
69:     } else if (m_config.m_ep_l2_ft_mode == 2) {
70:       const ep_l2::PayloadHandle free = m_ep_l2_payload.preview_free(
71:           ep_l2_payload_store::RESIDENT, index % 4);
72:       if (free.valid()) {
73:         if (!free.generation) return false; // preview must not wrap generation
74:         landing = free.payload_id;
75:       } else {
76:         if (!alias_payload.valid() || alias_payload.payload_id % 4 != index % 4 ||
77:             alias_payload.generation >= std::numeric_limits<unsigned>::max() - 1)
78:           return false;
79:         landing = alias_payload.payload_id;
80:       }
81:     } else {
82:       const ep_l2_payload_store::slot &free = m_ep_l2_payload.resident(landing);
83:       if (free.occupied() || free.generation == std::numeric_limits<unsigned>::max())
84:         return false;
85:     }
86:     assert(landing % 4 == index % 4);
87:   } else if (!m_ep_l2_payload.handle_owner_matches(handle, owner)) {
88:     return false;
89:   }
90:   // Commit starts here: every resource and refusal has been previewed above.
91:   if(m_config.ep_l2_large_enabled() && status==MISS && !m_tag_array->get_block(index)->is_invalid_line())
92:     ++large_prefill_clean_victims;
93:   if (has_alias) {
94:     ep_l2::PayloadHandle released;
95:     assert(m_tvd->reclaim(alias, released, ft_physical_cycle()) == tvd_directory::OK);
96:     assert(released == alias_payload);
97:     m_ep_l2_payload.release(released);
98:   }
99:   if (status == MISS) {
100:     if (live) m_ep_l2_payload.release(handle);
101:     handle = m_ep_l2_payload.reserve(landing, ep_l2_payload_store::RESIDENT,
102:         owner, ep_l2_payload_store::RESIDENT_VALID);
103:     set_tag_payload_handle(index, handle);
104:   }
105:   baseline_cache::force_tag_access(addr, time, mask);
106:   unsigned actual_index = (unsigned)-1;
107:   assert(m_tag_array->probe(owner, actual_index, mask, true, true) == HIT &&
108:          actual_index == index && "host prefill must commit the pre-reserved Tag index");
109:   ep_l2_payload_store::slot &slot = m_ep_l2_payload.inspect_mutable(handle);
110:   slot.ready_sector_mask |= mask;
111:   // Dataless host initialization has the same explicit version-zero symbol as
112:   // ordinary untouched lower memory, not fabricated numerical payload bytes.
113:   for (unsigned sector = 0; sector < 4; ++sector)
114:     if (mask.test(sector)) slot.versions[sector] = 0;
115:   slot.status = m_tag_array->block_is_modified(index) ?
116:       ep_l2_payload_store::RESIDENT_DIRTY : ep_l2_payload_store::RESIDENT_VALID;
117:   if(m_ro)m_ro->prefill_complete(index,handle,owner,mask);
118:   assert(m_ep_l2_payload.ownership_consistent());
119:   return true;
120: }
